select a.first_name , a.last_name 
from actor a left join film_actor fa on a.actor_id = fa.actor_id 
where  fa.film_id is null;

SELECT p.payment_id, p.amount, c2.first_name, c2.last_name 
 FROM payment p join customer c2 on p.customer_id = c2.customer_id 
 WHERE rental_id IS NULL;

SELECT p.payment_id, p.amount, c2.first_name, c2.last_name , c2.email
 FROM payment p join customer c2 on p.customer_id = c2.customer_id 
 WHERE rental_id IS NULL;
